// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DEP_BANK, LogFile} from "../src/DEP_BANK.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    DEP_BANK c;
    LogFile log_;

    function setUp() public {
        c = new DEP_BANK();
        log_ = new LogFile();
        c.SetLogFile(address(log_));
    }

    function testFuzz_property(uint256 balance, uint256 amount) public {
        vm.assume(balance <= VALUE_CAP);
        amount = bound(amount, 1, type(uint128).max);
        balance = bound(balance, amount, type(uint128).max);
        vm.deal(address(this), balance);
        Reentrant reentrant = new Reentrant(c);
        vm.deal(address(reentrant), balance);

        vm.prank(address(reentrant));
        bool okDeposit1; try c.Deposit{value: balance}() { okDeposit1 = true; } catch { okDeposit1 = false; }
        require(okDeposit1, "deposit1");

        // Ensure the contract has enough Ether to pay out amount.
        vm.deal(address(c), address(c).balance + amount);
        reentrant.collect(amount);

        assertTrue(reentrant.valueAtCallback() == balance - amount);
    }
}

contract Reentrant {
    DEP_BANK public c;
    uint256 public valueAtCallback;
    bool private entered;

    constructor(DEP_BANK _c) {
        c = _c;
    }

    function collect(uint256 _amount) external {
        c.Collect(_amount);
    }

    receive() external payable {
        if (!entered) {
            entered = true;
            valueAtCallback = c.balances(address(this));
        }
    }
}
